import os
import torch
import numpy as np
import random


class Config:
    """
    Central configuration for the Cassava Leaf Disease Classification task.
    Defines hyperparameters, file paths, and setup utilities for the ResNet-18 baseline.
    """

    # ==========================================
    # Reproducibility
    # ==========================================
    SEED = 42

    # ==========================================
    # Data Paths
    # ==========================================
    INPUT_ROOT = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided scripts
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Image directories (relative to INPUT_ROOT, handled by file_path in metadata)
    TRAIN_IMAGES_DIR = os.path.join(INPUT_ROOT, "train_images")
    TEST_IMAGES_DIR = os.path.join(INPUT_ROOT, "test_images")

    # ==========================================
    # Output Paths
    # ==========================================
    # Working directory for checkpoints and intermediate files
    WORKING_DIR = "./working/idea_1"

    # Model checkpoint location
    MODEL_CHECKPOINT_PATH = os.path.join(WORKING_DIR, "resnet18_best.pth")

    # Submission directory and file
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Model Architecture
    # ==========================================
    MODEL_NAME = "resnet18"
    NUM_CLASSES = 5
    PRETRAINED = True

    # ==========================================
    # Data Processing
    # ==========================================
    IMAGE_SIZE = 224
    # ImageNet normalization statistics
    MEAN = [0.485, 0.456, 0.406]
    STD = [0.229, 0.224, 0.225]

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    BATCH_SIZE = 64  # Adjusted for A100 GPU
    LEARNING_RATE = 1e-4
    NUM_EPOCHS = 10
    PATIENCE = 5  # Early stopping patience
    NUM_WORKERS = 4  # For DataLoader

    # ==========================================
    # Debugging / Development
    # ==========================================
    DEBUG = False  # Set to True to run on a small subset
    DEBUG_SUBSET_SIZE = 100  # Number of samples to use in debug mode

    @classmethod
    def setup(cls):
        """
        Prepares the environment by creating necessary directories and setting seeds.
        """
        # Create directories
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set random seeds
        cls.set_seed()

    @classmethod
    def set_seed(cls):
        """
        Sets the random seed for Python, NumPy, and PyTorch to ensure reproducibility.
        """
        random.seed(cls.SEED)
        np.random.seed(cls.SEED)
        torch.manual_seed(cls.SEED)
        torch.cuda.manual_seed(cls.SEED)
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False

    @classmethod
    def get_device(cls):
        """
        Returns the computing device (CUDA or CPU).
        """
        return torch.device("cuda" if torch.cuda.is_available() else "cpu")
